    SPRING("春"), SUMMER("夏"), AUTUMN("秋"), WINTER("冬");

    private final String japanese;

    Season(String japanese) {
        this.japanese = japanese;
    }

    String japanese() {
        return japanese;
    }
}

public class Main {
    public static void main(String[] args) {
        for (Season s : Season.values()) {
            System.out.println(s.ordinal() + " " + s.name() + " " + s.japanese());
        }

        System.out.println("個数: " + Season.values().length);

        Season s = Season.valueOf("SUMMER");
        System.out.println("valueOf: " + s.japanese());
        System.out.println("== で比較: " + (s == Season.SUMMER));
    }
}

