    Season(String japanese) {
        this.japanese = japanese;
    }

    String japanese() {
        return japanese;
    }
}

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int k = sc.nextInt();

        for (int i = 0; i < k; i++) {
            String name = sc.next();
            try {
                Season s = Season.valueOf(name);
                System.out.println(s.name() + " " + s.ordinal() + " " + s.japanese());
